00162     protected function replaceAll($params)
00163     {
00164         $content = file_get_contents( $this->bearsamppConf );
00165 
00166         foreach ( $params as $key => $value ) {
00167             $content                      = preg_replace( '|' . $key . ' = .*|', $key . ' = ' . '"' . $value . '"', $content );
00168             $this->bearsamppConfRaw[$key] = $value;
00169             switch ( $key ) {
00170                 case self::LOCAL_CFG_PORT:
00171                     $this->port = $value;
00172                     break;
00173                 case self::LOCAL_CFG_SSL_PORT:
00174                     $this->sslPort = $value;
00175                     break;
00176             }
00177         }
00178 
00179         file_put_contents( $this->bearsamppConf, $content );
00180     }
