00212             $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00213 
00214             return true;
00215         }
00216 
00217         Log::debug( $this->getName() . ' port in used: ' . $port . ' - ' . $isPortInUse );
00218 
