00231     public function checkPort($port, $ssl = false, $showWindow = false)
00232     {
00233         global $bearsamppLang, $bearsamppWinbinder;
00234         $boxTitle = sprintf( $bearsamppLang->getValue( Lang::CHECK_PORT_TITLE ), $this->getName(), $port );
00235 
00236         if ( !Util::isValidPort( $port ) ) {
00237             Log::error( $this->getName() . ' port not valid: ' . $port );
00238 
00239             return false;
00240         }
00241 
00242         $headers = HttpClient::getHttpHeaders( 'http' . ($ssl ? 's' : '') . '://localhost:' . $port . '/' . Path::getWebResourcesPath() . '/ping.php' );
00243         if ( !empty( $headers ) ) {
00244             foreach ( $headers as $row ) {
00245                 if ( UtilString::startWith( $row, 'Server: ' ) || UtilString::startWith( $row, 'server: ' ) ) {
00246                     Log::debug( $this->getName() . ' port ' . $port . ' is used by: ' . $this->getName() . ' ' . str_replace( 'Server: ', '', str_replace( 'server: ', '', trim( $row ) ) ) );
00247                     if ( $showWindow ) {
00248                         $bearsamppWinbinder->messageBoxInfo(
00249                             sprintf( $bearsamppLang->getValue( Lang::PORT_USED_BY ), $port, str_replace( 'Server: ', '', str_replace( 'server: ', '', trim( $row ) ) ) ),
00250                             $boxTitle
00251                         );
00252                     }
00253 
00254                     return true;
00255                 }
00256             }
00257             Log::debug( $this->getName() . ' port ' . $port . ' is used by another application' );
00258             if ( $showWindow ) {
00259                 $bearsamppWinbinder->messageBoxWarning(
00260                     sprintf( $bearsamppLang->getValue( Lang::PORT_NOT_USED_BY ), $port ),
00261                     $boxTitle
00262                 );
00263             }
00264         }
00265         else {
00266             Log::debug( $this->getName() . ' port ' . $port . ' is not used' );
00267             if ( $showWindow ) {
00268                 $bearsamppWinbinder->messageBoxError(
00269                     sprintf( $bearsamppLang->getValue( Lang::PORT_NOT_USED ), $port ),
00270                     $boxTitle
00271                 );
00272             }
00273         }
00274 
00275         return false;
00276     }
