00302     protected function updateConfig($version = null, $sub = 0, $showWindow = false)
00303     {
00304         global $bearsamppRoot, $bearsamppLang, $bearsamppBins, $bearsamppWinbinder;
00305 
00306         if ( !$this->enable ) {
00307             return true;
00308         }
00309 
00310         $version = $version == null ? $this->version : $version;
00311         Log::debug( ($sub > 0 ? str_repeat( ' ', 2 * $sub ) : '') . 'Update ' . $this->name . ' ' . $version . ' config' );
00312 
00313         $boxTitle = sprintf( $bearsamppLang->getValue( Lang::SWITCH_VERSION_TITLE ), $this->getName(), $version );
00314 
00315         $conf          = str_replace( 'apache' . $this->getVersion(), 'apache' . $version, $this->getConf() );
00316         $bearsamppConf = str_replace( 'apache' . $this->getVersion(), 'apache' . $version, $this->bearsamppConf );
00317 
00318         $tsDll = $bearsamppBins->getPhp()->getTsDll();
00319 
00320         $apachePhpModuleName = null;
00321         if ( $tsDll !== false ) {
00322             $apachemoduleNamePrefix = substr( $tsDll, 0, 4 );
00323             $apachePhpModuleName    = ($apachemoduleNamePrefix == 'php8' ? 'php' : $apachemoduleNamePrefix) . '_module';
00324         }
00325         $apachePhpModulePath = $bearsamppBins->getPhp()->getApacheModule( $version );
00326         $apachePhpModuleDll  = basename( $apachePhpModulePath );
00327 
00328         Log::debug( ($sub > 0 ? str_repeat( ' ', 2 * $sub ) : '') . 'PHP TsDll found: ' . $tsDll );
00329         Log::debug( ($sub > 0 ? str_repeat( ' ', 2 * $sub ) : '') . 'PHP Apache module found: ' . $apachePhpModulePath );
00330 
00331         if ( !file_exists( $conf ) || !file_exists( $bearsamppConf ) ) {
00332             Log::error( 'bearsampp config files not found for ' . $this->getName() . ' ' . $version );
00333             if ( $showWindow ) {
00334                 $bearsamppWinbinder->messageBoxError(
00335                     sprintf( $bearsamppLang->getValue( Lang::BEARSAMPP_CONF_NOT_FOUND_ERROR ), $this->getName() . ' ' . $version ),
00336                     $boxTitle
00337                 );
00338             }
00339 
00340             return false;
00341         }
00342 
00343         $bearsamppConfRaw = parse_ini_file( $bearsamppConf );
00344         if ( $bearsamppConfRaw === false || !isset( $bearsamppConfRaw[self::ROOT_CFG_VERSION] ) || $bearsamppConfRaw[self::ROOT_CFG_VERSION] != $version ) {
00345             Log::error( 'bearsampp config file malformed for ' . $this->getName() . ' ' . $version );
00346             if ( $showWindow ) {
00347                 $bearsamppWinbinder->messageBoxError(
00348                     sprintf( $bearsamppLang->getValue( Lang::BEARSAMPP_CONF_MALFORMED_ERROR ), $this->getName() . ' ' . $version ),
00349                     $boxTitle
00350                 );
00351             }
00352 
00353             return false;
00354         }
00355 
00356         if ( $tsDll === false || $apachePhpModulePath === false ) {
00357             Log::debug( $this->getName() . ' ' . $version . ' does not seem to be compatible with PHP ' . $bearsamppBins->getPhp()->getVersion() );
00358             if ( $showWindow ) {
00359                 $bearsamppWinbinder->messageBoxError(
00360                     sprintf( $bearsamppLang->getValue( Lang::APACHE_INCPT ), $version, $bearsamppBins->getPhp()->getVersion() ),
00361                     $boxTitle
00362                 );
00363             }
00364 
00365             return false;
00366         }
00367 
00368         // httpd.conf
00369         $this->setVersion( $version );
00370 
00371         // conf
00372         Log::debug( 'httpd.conf = ' . $conf );
00373         Util::replaceInFile( $conf, array(
00374             // PHP module
00375             '/^#?PHPIniDir\s.*/'                          => ($bearsamppBins->getPhp()->isEnable() ? '' : '#') . 'PHPIniDir "' . Path::getModuleSymlinkPath($bearsamppBins->getPhp()) . '"',
00376             '/^#?LoadFile\s.*php.ts\.dll.*/'              => ($bearsamppBins->getPhp()->isEnable() ? '' : '#') . (!file_exists( Path::getModuleSymlinkPath($bearsamppBins->getPhp()) . '/' . $tsDll ) ? '#' : '') . 'LoadFile "' . Path::getModuleSymlinkPath($bearsamppBins->getPhp()) . '/' . $tsDll . '"',
00377             '/^#?LoadModule\sphp.*/'                      => ($bearsamppBins->getPhp()->isEnable() ? '' : '#') . 'LoadModule ' . $apachePhpModuleName . ' "' . Path::getModuleSymlinkPath($bearsamppBins->getPhp()) . '/' . $apachePhpModuleDll . '"',
00378             '/^#?LoadModule\sphp_*/'                      => ($bearsamppBins->getPhp()->isEnable() ? '' : '#') . 'LoadModule ' . $apachePhpModuleName . ' "' . Path::getModuleSymlinkPath($bearsamppBins->getPhp()) . '/' . $apachePhpModuleDll . '"',
00379 
00380 
00381             // Port
00382             '/^Listen\s(\d+)/'                            => 'Listen ' . $this->port,
00383             '/^ServerName\s+([a-zA-Z0-9.]+):(\d+)/'       => 'ServerName {{1}}:' . $this->port,
00384             '/^NameVirtualHost\s+([a-zA-Z0-9.*]+):(\d+)/' => 'NameVirtualHost {{1}}:' . $this->port,
00385             '/^<VirtualHost\s+([a-zA-Z0-9.*]+):(\d+)>/'   => '<VirtualHost {{1}}:' . $this->port . '>'
00386         ) );
00387 
00388         // vhosts
00389         foreach ( $this->getVhosts() as $vhost ) {
00390             Util::replaceInFile( Path::getVhostsPath() . '/' . $vhost . '.conf', array(
00391                 '/^<VirtualHost\s+([a-zA-Z0-9.*]+):(\d+)>$/' => '<VirtualHost {{1}}:' . $this->port . '>$'
00392             ) );
00393         }
00394 
00395         // www .htaccess
00396         Util::replaceInFile( Path::getWwwPath() . '/.htaccess', array(
00397             '/(.*)http:\/\/localhost(.*)/' => '{{1}}http://localhost' . ($this->port != 80 ? ':' . $this->port : '') . '/$1 [QSA,R=301,L]',
00398         ) );
00399 
00400         return true;
00401     }
