00423     public function getModulesFromConf()
00424     {
00425         $result = array();
00426 
00427         if ( !$this->enable ) {
00428             return $result;
00429         }
00430 
00431         $confContent = file( $this->getConf() );
00432         foreach ( $confContent as $row ) {
00433             $modMatch = array();
00434             if ( preg_match( '/^(#)?LoadModule\s*([a-z0-9_-]+)\s*"?(.*)"?/i', $row, $modMatch ) ) {
00435                 $name = $modMatch[2];
00436                 //$path = $modMatch[3];
00437                 if ( !UtilString::startWith( $name, 'php' ) ) {
00438                     if ( $modMatch[1] == '#' ) {
00439                         $result[$name] = ActionSwitchApacheModule::SWITCH_OFF;
00440                     }
00441                     else {
00442                         $result[$name] = ActionSwitchApacheModule::SWITCH_ON;
00443                     }
00444                 }
00445             }
00446         }
00447 
00448         ksort( $result );
00449 
00450         return $result;
00451     }
