00475     private function getModulesFromFolder()
00476     {
00477         $result = array();
00478 
00479         if ( !$this->enable ) {
00480             return $result;
00481         }
00482 
00483         $handle = @opendir( $this->getModulesPath() );
00484         if ( !$handle ) {
00485             return $result;
00486         }
00487 
00488         while ( false !== ($file = readdir( $handle )) ) {
00489             if ( $file != '.' && $file != '..' && UtilString::startWith( $file, 'mod_' ) && (UtilString::endWith( $file, '.so' ) || UtilString::endWith( $file, '.dll' )) ) {
00490                 $name          = str_replace( array('mod_', '.so', '.dll'), '', $file ) . '_module';
00491                 $result[$name] = ActionSwitchApacheModule::SWITCH_OFF;
00492             }
00493         }
00494 
00495         closedir( $handle );
00496         ksort( $result );
00497 
00498         return $result;
00499     }
