00560     public function getVhostsUrl()
00561     {
00562         global $bearsamppRoot;
00563         $result = array();
00564 
00565         foreach ( $this->getVhosts() as $vhost ) {
00566             $vhostContent = file( Path::getVhostsPath() . '/' . $vhost . '.conf' );
00567             foreach ( $vhostContent as $vhostLine ) {
00568                 $vhostLine = trim( $vhostLine );
00569                 $enabled   = !UtilString::startWith( $vhostLine, '#' );
00570                 if ( preg_match_all( '/ServerName\s+(.*)/', $vhostLine, $matches ) ) {
00571                     foreach ( $matches as $match ) {
00572                         $found = isset( $match[1] ) ? trim( $match[1] ) : trim( $match[0] );
00573                         if ( filter_var( 'http://' . $found, FILTER_VALIDATE_URL ) !== false ) {
00574                             $result[$found] = $enabled;
00575                             break 2;
00576                         }
00577                     }
00578                 }
00579             }
00580         }
00581 
00582         return $result;
00583     }
