00619     public function getCmdLineOutput($cmd)
00620     {
00621         $result = array(
00622             'syntaxOk' => false,
00623             'content'  => null,
00624         );
00625 
00626         if ( file_exists( $this->getExe() ) ) {
00627             $tmpResult = Batch::exec( 'apacheGetCmdLineOutput', '"' . $this->getExe() . '" ' . $cmd );
00628             if ( $tmpResult !== false && is_array( $tmpResult ) ) {
00629                 $result['syntaxOk'] = trim( $tmpResult[count( $tmpResult ) - 1] ) == 'Syntax OK';
00630                 if ( $result['syntaxOk'] ) {
00631                     unset( $tmpResult[count( $tmpResult ) - 1] );
00632                 }
00633                 $result['content'] = implode( PHP_EOL, $tmpResult );
00634             }
00635         }
00636 
00637         return $result;
00638     }
