00647     private function getOnlineContent($version = null)
00648     {
00649         $version = $version != null ? $version : $this->getVersion();
00650         $result  = self::TAG_START_SWITCHONLINE . PHP_EOL;
00651 
00652         if ( UtilString::startWith( $version, '2.4' ) ) {
00653             $result .= 'Require all granted' . PHP_EOL;
00654         }
00655         else {
00656             $result .= 'Order Allow,Deny' . PHP_EOL .
00657                 'Allow from all' . PHP_EOL;
00658         }
00659 
00660         return $result . self::TAG_END_SWITCHONLINE;
00661     }
00662 
00670     private function getOfflineContent($version = null)
00671     {
00672         $version = $version != null ? $version : $this->getVersion();
00673         $result  = self::TAG_START_SWITCHONLINE . PHP_EOL;
00674 
00675         if ( UtilString::startWith( $version, '2.4' ) ) {
00676             $result .= 'Require local' . PHP_EOL;
00677         }
00678         else {
00679             $result .= 'Order Deny,Allow' . PHP_EOL .
00680                 'Deny from all' . PHP_EOL .
00681                 'Allow from 127.0.0.1 ::1' . PHP_EOL;
00682         }
00683 
00684         return $result . self::TAG_END_SWITCHONLINE;
00685     }
