00776     public function refreshConf($putOnline)
00777     {
00778         if ( !$this->enable ) {
00779             return;
00780         }
00781 
00782         $onlineContent  = $this->getOnlineContent();
00783         $offlineContent = $this->getOfflineContent();
00784 
00785         $conf = file_get_contents( $this->getConf() );
00786         Log::trace( 'refreshConf ' . $this->getConf() );
00787         preg_match( '/' . self::TAG_START_SWITCHONLINE . '(.*?)' . self::TAG_END_SWITCHONLINE . '/s', $conf, $matches );
00788         Log::trace( isset( $matches[1] ) ? print_r( $matches[1], true ) : 'N/A' );
00789 
00790         if ( $putOnline ) {
00791             $conf = preg_replace( '/' . self::TAG_START_SWITCHONLINE . '(.*?)' . self::TAG_END_SWITCHONLINE . '/s', $onlineContent, $conf, -1, $count );
00792         }
00793         else {
00794             $conf = preg_replace( '/' . self::TAG_START_SWITCHONLINE . '(.*?)' . self::TAG_END_SWITCHONLINE . '/s', $offlineContent, $conf, -1, $count );
00795         }
00796         file_put_contents( $this->getConf(), $conf );
00797         Log::debug( 'Refresh ' . $this->getConf() . ': ' . $count . ' occurrence(s) replaced' );
00798 
00799         $sslConf = file_get_contents( $this->getSslConf() );
00800         Log::trace( 'refreshConf ' . $this->getSslConf() );
00801         preg_match( '/' . self::TAG_START_SWITCHONLINE . '(.*?)' . self::TAG_END_SWITCHONLINE . '/s', $sslConf, $matches );
00802         Log::trace( isset( $matches[1] ) ? print_r( $matches[1], true ) : 'N/A' );
00803 
00804         if ( $putOnline ) {
00805             $sslConf = preg_replace( '/' . self::TAG_START_SWITCHONLINE . '(.*?)' . self::TAG_END_SWITCHONLINE . '/s', $onlineContent, $sslConf, -1, $count );
00806         }
00807         else {
00808             $sslConf = preg_replace( '/' . self::TAG_START_SWITCHONLINE . '(.*?)' . self::TAG_END_SWITCHONLINE . '/s', $offlineContent, $sslConf, -1, $count );
00809         }
00810         file_put_contents( $this->getSslConf(), $sslConf );
00811         Log::debug( 'Refresh ' . $this->getSslConf() . ': ' . $count . ' occurrence(s) replaced' );
00812     }
