00893     public function setEnable($enabled, $showWindow = false)
00894     {
00895         global $bearsamppConfig, $bearsamppLang, $bearsamppWinbinder;
00896 
00897         if ( $enabled == Config::ENABLED && !is_dir( $this->currentPath ) ) {
00898             Log::debug( $this->getName() . ' cannot be enabled because bundle ' . $this->getVersion() . ' does not exist in ' . $this->currentPath );
00899             if ( $showWindow ) {
00900                 $bearsamppWinbinder->messageBoxError(
00901                     sprintf( $bearsamppLang->getValue( Lang::ENABLE_BUNDLE_NOT_EXIST ), $this->getName(), $this->getVersion(), $this->currentPath ),
00902                     sprintf( $bearsamppLang->getValue( Lang::ENABLE_TITLE ), $this->getName() )
00903                 );
00904             }
00905             $enabled = Config::DISABLED;
00906         }
00907 
00908         Log::info( $this->getName() . ' switched to ' . ($enabled == Config::ENABLED ? 'enabled' : 'disabled') );
00909         $this->enable = $enabled == Config::ENABLED;
00910         $bearsamppConfig->replace( self::ROOT_CFG_ENABLE, $enabled );
00911 
00912         $this->reload();
00913         if ( $this->enable ) {
00914             Util::installService( $this, $this->port, self::CMD_SYNTAX_CHECK, $showWindow );
00915         }
00916         else {
00917             Util::removeService( $this->service, $this->name );
00918         }
00919     }
